shader:
// Lens Warp - push through a lens.
// A bulges (barrel, corners pinned) while the camera accelerates into the centre; the hard cut hides inside
// the fastest, most smeared frames; B lands minified inside the same barrel, so the push carries on, and
// decelerates to flat and sharp. Centre magnification only ever rises, on both sides of the cut.
// 48-tap temporal motion blur: every tap re-evaluates the lens at its own white-noise-jittered, Hann-weighted
// shutter time; each side keeps its own shutter (extrapolated past the cut on its own lens), so no frame is
// ever a double exposure of A and B.
// Chromatic aberration = spectral shutter tilt (red weighted to the start of every streak, blue to the end):
// it exists only where the lens moves, grows toward the edges, never makes green/purple bands.
// While B is minified, its mirrored surround gets extra radial smear that grows with the distance past the
// frame edge, so the landing reads as zoom streaks, never as a reflected copy of the picture.

const float LW_CUT = 0.5;
const int LW_TAPS = 48;

uint lwHash(uint v) {                       // PCG hash: white noise, no diagonal hatching
    uint s = v * 747796405u + 2891336453u;
    uint w = ((s >> ((s >> 28u) + 4u)) ^ s) * 277803737u;
    return (w >> 22u) ^ w;
}
float lwU01(uint v) { return float(v >> 8u) * (1.0 / 16777216.0); }

// A: t 0 (start) .. 1 (cut). x = source scale at rn2 (<1 magnifies), y = lens envelope, z = smear/defocus envelope
vec3 lwLensA(float t, float rn2) {
    float t2 = t * t;
    float t4 = t2 * t2;
    float ew = t2 * t * sqrt(t);                         // bulge: late, strong ease-in
    float k = warp * ew;
    float s = (1.0 + k * rn2) / ((1.0 + k) * (1.0 + 0.6 * zoom * t4));
    return vec3(s, ew, t4);
}

// B: t 1 (cut) .. 0 (end). Centre-normalised barrel: the bulge can never cancel the push at the centre
vec3 lwLensB(float t, float rn2) {
    float t2 = t * t;
    float t4 = t2 * t2;
    float lb = 0.2 + 0.15 * warp + 0.18 * zoom;          // landing minification (log), matched to A's speed
    float sb = exp(lb * t4 * t2);                        // ease-out: fastest at the cut
    float ew = t2 * t;
    float b = 1.0 + 0.4 * warp * ew * rn2;
    float cap = max(2.4 / sb, 1.0);                      // corners never sample beyond 2.4x
    float hh = clamp(0.5 + 0.5 * (cap - b) / 0.12, 0.0, 1.0);
    b = mix(cap, b, hh) - 0.12 * hh * (1.0 - hh);
    return vec3(sb * b, ew, t4);
}

vec4 transition(vec2 uv) {
    if (progress <= 0.0) return getA(uv);
    if (progress >= 1.0) return getB(uv);

    vec2 asp = vec2(ratio, 1.0);
    vec2 hb = 0.5 * asp;                                          // frame half size in lens space
    vec2 d = (uv - 0.5) * asp;
    float rc2 = 0.25 * (ratio * ratio + 1.0);
    float rn2 = dot(d, d) / rc2;                                  // 0 centre .. 1 corners

    uvec2 ip = uvec2(gl_FragCoord.xy);
    uint seed = lwHash(ip.x + lwHash(ip.y + lwHash(uint(time * 60.0 + 0.5))));
    float n1 = lwU01(seed);                                       // shutter jitter (1D, stratified)

    float shutter = 0.05 * blur;                                  // ~250 deg at 30 fps
    bool isB = progress >= LW_CUT;
    // each side's shutter is centred on the frame time; near the cut it runs on that side's own lens
    // extrapolated past the cut (A a little further in, B a little more minified), never on the other clip
    float pc = progress;
    float qlo = isB ? LW_CUT - 0.5 * shutter : 0.0;
    float qhi = isB ? 1.0 : LW_CUT + 0.5 * shutter;

    float tc = isB ? (1.0 - pc) / (1.0 - LW_CUT) : pc / LW_CUT;
    vec3 lc = isB ? lwLensB(tc, rn2) : lwLensA(tc, rn2);
    // how far B's minified landing reaches past its frame edge (0 inside)
    vec2 sp = abs(d * lc.x) / hb;
    float oob = isB ? max(sp.x, sp.y) - 1.0 : -1.0;
    // radial lens smear riding the shutter axis (same direction as the push)
    float smear = blur * ((isB ? 0.1 : 0.16) * lc.z + 0.05 * lc.y * lc.y * rn2) + 0.8 * smoothstep(-0.06 * tc, 0.25, oob);
    // streak length (px) over this frame's shutter, from the lens at both shutter ends
    float q0 = clamp(pc - 0.5 * shutter, qlo, qhi);
    float q1 = clamp(pc + 0.5 * shutter, qlo, qhi);
    float s0 = isB ? lwLensB((1.0 - q0) / (1.0 - LW_CUT), rn2).x : lwLensA(q0 / LW_CUT, rn2).x;
    float s1 = isB ? lwLensB((1.0 - q1) / (1.0 - LW_CUT), rn2).x : lwLensA(q1 / LW_CUT, rn2).x;
    float streak = (abs(log(s1 / s0)) + smear) * length(d) * resolution.y;
    // small screen-space defocus where the zoom leaves the image still (the centre), so the frames at the cut
    // are soft everywhere; faded out along streaks, where a fixed disc would print ghost contours
    float dofR = 0.0065 * lc.z * (0.5 + 0.5 * blur) / (1.0 + streak * streak / 36.0);
    // spectral tilt: lateral colour split along the streaks (A's streaks are shorter, so it ramps in earlier)
    float tA = min(tc, 1.0);
    float sig = chroma * rn2 * (isB ? 2.2 * lc.y : 4.5 * tA * tA * sqrt(tA));
    sig = 2.0 * tanh(0.5 * sig);                                  // soft cap: a split, never a 3-band rainbow

    vec3 acc = vec3(0.0);
    vec3 wsum = vec3(0.0);
    for (int j = 0; j < LW_TAPS; j++) {
        float fj = float(j);
        float u = (fj + n1) / float(LW_TAPS);                     // stratified shutter position 0..1
        float q = clamp(pc + (u - 0.5) * shutter, qlo, qhi);
        float tq = isB ? (1.0 - q) / (1.0 - LW_CUT) : q / LW_CUT;
        vec3 l = isB ? lwLensB(tq, rn2) : lwLensA(tq, rn2);
        float s = l.x * (1.0 - (u - 0.5) * smear);
        // small fixed defocus disc: 24 Vogel points (decorrelated from the shutter), each used twice as an
        // antithetic pair; at <= 4 px it is noise-free and too dense to show ghost contours
        float hj = floor(fj * 0.5);
        float kd = mod(hj * 7.0, 24.0);
        float rr = sqrt((kd + 0.5) / 24.0) * (fj - 2.0 * hj > 0.5 ? -dofR : dofR);
        float ang = kd * 2.3999632;
        vec2 suv = (d + vec2(cos(ang), sin(ang)) * rr) * s / asp + 0.5;
        vec3 c = isB ? getB(suv).rgb : getA(suv).rgb;
        float hs = sin(3.1415927 * u);
        float ex = sig * (1.0 - 2.0 * u);
        vec3 wv = (0.02 + hs * hs) * vec3(exp(ex), 1.0, exp(-ex)); // Hann shutter, red early / blue late
        acc += c * wv;
        wsum += wv;
    }
    vec3 col = acc / wsum;

    // lens vignette, only while the lens is active
    float tn = isB ? (1.0 - progress) / (1.0 - LW_CUT) : progress / LW_CUT;
    col *= 1.0 - 0.45 * tn * tn * smoothstep(0.25, 1.0, rn2);
    return vec4(clamp(col, 0.0, 1.0), 1.0);
}
